from collections import Counter, deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            if (all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0, c1 + 1)) and
                all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0, r1 + 1))):
                fill = 7 if ((r1 - r0 - 1) * (c1 - c0 - 1)) % 2 else 2
                for y in range(r0 + 1, r1):
                    for x in range(c0 + 1, c1):
                        out[y][x] = fill
    return out
